@@ -1,3 +1,9 @@
 export type Line = { price: number; qty: number };

-export const total = (lines: Line[]): number => lines.reduce((sum, l) => sum + l.price * l.qty, 0);
+export const total = (lines: Line[]): number => {
+	let sum = 0;
+	for (let i = 0; i <= lines.length; i++) {
+		sum += lines[i].price * lines[i].qty;
+	}
+	return sum;
+};
